<script setup>
import { ref, computed, onMounted, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { supabase } from "../lib/supabaseClient";
const route=useRoute();const router=useRouter();const institution=ref(null);const posts=ref([]);const loading=ref(true);const errorText=ref("");const id=computed(()=>String(route.params.id||""));
function initials(name){return String(name||"TH").trim().split(/\s+/).slice(0,2).map(w=>w[0]?.toUpperCase()).join("");}function url(v){if(!v)return"";return /^https?:\/\//i.test(v)?v:`https://${v}`;}function whatsapp(){const raw=String(institution.value?.phone||"").replace(/\D/g,"");const p=raw.length===8?`503${raw}`:raw;const msg=encodeURIComponent(`Hola, encontré a ${institution.value?.name} por medio de Thrive y quisiera obtener más información.`);window.open(p?`https://wa.me/${p}?text=${msg}`:`https://wa.me/?text=${msg}`,"_blank","noopener,noreferrer");}function formatDate(v){return v?new Intl.DateTimeFormat("es-SV",{day:"numeric",month:"short",year:"numeric"}).format(new Date(v)):"";}
async function load(){loading.value=true;errorText.value="";try{const{data,error}=await supabase.rpc("get_public_institutions");if(error)throw error;const row=(data||[]).find(i=>i.id===id.value);if(!row){errorText.value="No encontramos esta institución.";return;}institution.value={id:row.id,name:row.institution_name,description:row.description||"",website:row.website||"",department:row.department||"",district:row.district||"",logoUrl:row.logo_url||"",phone:row.phone||""};const{data:postRows,error:postError}=await supabase.from("institution_posts").select("id,title,description,post_type,location,external_url,event_date,published_at").eq("institution_id",id.value).eq("status","published").order("published_at",{ascending:false}).limit(6);if(!postError)posts.value=postRows||[];}catch(e){console.error(e);errorText.value="No fue posible cargar el perfil institucional.";}finally{loading.value=false;}}
watch(id,load);onMounted(load);
</script>
<template><div class="min-h-screen bg-[#F8FBFC] text-gray-700"><header class="sticky top-0 z-40 bg-[#F8FBFC]/95 backdrop-blur"><div class="mx-auto flex max-w-[1100px] items-center justify-between px-4 py-3"><button class="flex h-11 w-11 items-center justify-center rounded-full bg-white text-[#0077B6] shadow-sm" @click="router.back()">←</button><p class="font-black text-[#0077B6]">Institución</p><div class="h-11 w-11"></div></div></header><main v-if="loading" class="py-28 text-center"><div class="mx-auto h-9 w-9 animate-spin rounded-full border-4 border-[#CAF0F8] border-t-[#00B4D8]"></div></main><main v-else-if="errorText" class="mx-auto max-w-xl px-5 py-24 text-center">{{ errorText }}</main><main v-else-if="institution" class="mx-auto max-w-[1100px] px-4 py-5 sm:px-6 lg:py-8"><section class="rounded-[30px] bg-gradient-to-br from-[#0077B6] to-[#00B4D8] p-6 text-white shadow-[0_18px_55px_rgba(0,119,182,.2)] sm:p-8"><div class="flex flex-col items-center gap-5 text-center sm:flex-row sm:text-left"><img v-if="institution.logoUrl" :src="institution.logoUrl" class="h-28 w-28 rounded-[30px] bg-white object-cover p-1"><div v-else class="flex h-28 w-28 items-center justify-center rounded-[30px] bg-white/15 text-2xl font-black">{{ initials(institution.name) }}</div><div><p class="text-xs font-black uppercase tracking-[.18em] text-white/65">Institución en Thrive</p><h1 class="mt-2 text-3xl font-black sm:text-4xl">{{ institution.name }}</h1><p class="mt-2 text-sm font-semibold text-white/70">{{ institution.district || institution.department || 'El Salvador' }}</p></div></div></section><section class="mt-5 grid gap-4 lg:grid-cols-[1.3fr_.7fr]"><article class="rounded-[26px] bg-white p-6 shadow-sm"><p class="text-xs font-black uppercase tracking-[.15em] text-[#00B4D8]">Sobre la institución</p><p class="mt-3 whitespace-pre-line text-sm leading-7 text-gray-500">{{ institution.description || 'Información institucional disponible en Thrive.' }}</p></article><article class="rounded-[26px] bg-white p-6 shadow-sm"><p class="text-xs font-black uppercase tracking-[.15em] text-[#00B4D8]">Contacto</p><div class="mt-4 space-y-2"><button v-if="institution.phone" class="w-full rounded-[16px] bg-[#25D366] px-4 py-3 font-black text-white" @click="whatsapp">Contactar por WhatsApp</button><a v-if="institution.website" :href="url(institution.website)" target="_blank" rel="noopener noreferrer" class="block w-full rounded-[16px] bg-[#0077B6] px-4 py-3 text-center font-black text-white">Visitar sitio web</a></div></article></section><section class="mt-8"><p class="text-xs font-black uppercase tracking-[.15em] text-[#00B4D8]">Actualidad</p><h2 class="mt-1 text-2xl font-black text-gray-800">Publicaciones recientes</h2><div v-if="posts.length" class="mt-4 grid gap-4 md:grid-cols-2"><article v-for="p in posts" :key="p.id" class="rounded-[24px] bg-white p-5 shadow-sm"><div class="flex items-center justify-between"><span class="rounded-full bg-[#EAF9FC] px-3 py-1 text-[10px] font-black uppercase text-[#0077B6]">{{ p.post_type }}</span><span class="text-xs text-gray-400">{{ formatDate(p.event_date || p.published_at) }}</span></div><h3 class="mt-3 text-lg font-black">{{ p.title }}</h3><p class="mt-2 line-clamp-3 text-sm leading-6 text-gray-500">{{ p.description }}</p><a v-if="p.external_url" :href="url(p.external_url)" target="_blank" rel="noopener noreferrer" class="mt-4 inline-block text-sm font-black text-[#0077B6]">Más información →</a></article></div><div v-else class="mt-4 rounded-[24px] bg-white p-7 text-sm text-gray-500 shadow-sm">No hay publicaciones recientes para mostrar.</div></section></main></div></template>
